.shell { display: grid; grid-template-columns: 232px minmax(0, 1fr); min-height: 100vh; }
.shell > div { min-width: 0; }
.sidebar { background: var(--surface); border-right: 1px solid var(--border); padding: 20px 14px; display: flex; flex-direction: column; gap: 4px; position: sticky; top: 0; height: 100vh; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 15px; padding: 4px 8px 18px; letter-spacing: 0.01em; }
.brand-mark { width: 26px; height: 26px; border-radius: 7px; background: var(--accent); color: var(--accent-ink); display: grid; place-items: center; font-size: 12px; font-weight: 800; }
.nav a { display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 8px; text-decoration: none; color: var(--ink-2); font-weight: 500; }
.nav a:hover { background: var(--surface-2); color: var(--ink); }
.nav a[aria-current="page"] { background: var(--surface-2); color: var(--ink); font-weight: 600; }
.nav svg { width: 18px; height: 18px; flex: none; }
.sidebar-foot { margin-top: auto; padding: 10px 8px 0; border-top: 1px solid var(--border); font-size: 12.5px; color: var(--muted); display: flex; flex-direction: column; gap: 6px; }
.sidebar-foot button { background: none; border: 0; padding: 0; color: var(--ink-2); cursor: pointer; text-align: left; text-decoration: underline; }

.main { padding: 24px 32px 48px; min-width: 0; }
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 18px; }
.page-head h1 { margin: 0; font-size: 26px; font-weight: 700; letter-spacing: -0.01em; }
.page-head p { margin: 4px 0 0; color: var(--ink-2); }
.head-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

.live { display: inline-flex; align-items: center; gap: 7px; font-size: 12.5px; color: var(--ink-2); }
.live-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--good); box-shadow: 0 0 0 0 rgba(12, 163, 12, 0.5); animation: pulse 2s infinite; }
.live-dot.stale { background: var(--muted); animation: none; }
@keyframes pulse { 70% { box-shadow: 0 0 0 7px rgba(12, 163, 12, 0); } 100% { box-shadow: 0 0 0 0 rgba(12, 163, 12, 0); } }
@media (prefers-reduced-motion: reduce) { .live-dot { animation: none; } }

.btn { display: inline-flex; align-items: center; gap: 7px; border: 1px solid var(--border); background: var(--surface); padding: 8px 13px; border-radius: 8px; cursor: pointer; font-weight: 600; font-size: 13px; text-decoration: none; white-space: nowrap; }
.btn:hover { background: var(--surface-2); }
.btn:disabled, .btn[aria-disabled="true"] { opacity: 0.55; cursor: default; pointer-events: none; }
.btn-primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.btn-primary:hover { background: var(--accent); opacity: 0.88; }
.btn-danger { color: var(--critical); }

.filters { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; margin-bottom: 18px; }
.seg { display: inline-flex; background: var(--surface); border: 1px solid var(--border); border-radius: 9px; padding: 3px; }
.seg button { border: 0; background: none; padding: 6px 12px; border-radius: 6px; cursor: pointer; font-weight: 600; font-size: 13px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
.seg button[aria-pressed="true"] { background: var(--surface-2); color: var(--ink); box-shadow: inset 0 0 0 1px var(--border); }
.select, .input { background: var(--surface); border: 1px solid var(--border); border-radius: 9px; padding: 8px 11px; font-size: 13px; }
.input { min-width: 240px; }
.key { display: inline-block; width: 12px; height: 2px; border-radius: 2px; }
.key-yt { background: var(--series-yt); }
.key-tt { background: var(--series-tt); }

.banner { border: 1px solid var(--border); background: var(--surface); border-left: 3px solid var(--critical); padding: 10px 14px; border-radius: 8px; margin-bottom: 16px; display: flex; gap: 10px; align-items: flex-start; }
.banner.info { border-left-color: var(--series-yt); }
.banner.ok { border-left-color: var(--good); }

.kpis { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin-bottom: 16px; }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); }
.kpi { padding: 16px 18px; }
.kpi-label { color: var(--ink-2); font-size: 13px; font-weight: 500; }
.kpi-value { font-size: 30px; font-weight: 650; margin: 6px 0 4px; letter-spacing: -0.01em; }
.kpi-note { font-size: 13px; color: var(--ink-2); font-weight: 600; margin-bottom: 2px; }
.delta { font-size: 12.5px; font-weight: 600; display: inline-flex; align-items: center; gap: 4px; }
.delta.up { color: var(--up); }
.delta.down { color: var(--down); }
.delta.flat { color: var(--muted); }
.delta small { color: var(--muted); font-weight: 400; }

.charts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-bottom: 16px; }
.chart-card { padding: 16px 18px 10px; }
.card-title { margin: 0; font-size: 15px; font-weight: 650; }
.card-sub { margin: 2px 0 0; color: var(--muted); font-size: 12.5px; }
.card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; margin-bottom: 8px; }
.legend { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 12.5px; color: var(--ink-2); margin-top: 8px; }
.legend span { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.tooltip { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 8px 11px; box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12); font-size: 12.5px; min-width: 150px; }
.tooltip-time { color: var(--muted); margin-bottom: 4px; }
.tooltip-row { display: flex; align-items: center; gap: 8px; justify-content: space-between; }
.tooltip-row b { font-size: 13.5px; }
.tooltip-row span { display: inline-flex; align-items: center; gap: 6px; color: var(--ink-2); }

.section { margin-bottom: 16px; }
.section-head { padding: 14px 18px; display: flex; justify-content: space-between; align-items: center; gap: 10px; border-bottom: 1px solid var(--border); }
.table-wrap { overflow-x: auto; }
table.data { width: 100%; border-collapse: collapse; font-size: 13px; }
table.data th { text-align: left; font-weight: 600; color: var(--muted); font-size: 12px; padding: 10px 14px; border-bottom: 1px solid var(--border); white-space: nowrap; }
table.data td { padding: 10px 14px; border-bottom: 1px solid var(--border); vertical-align: middle; }
table.data tr:last-child td { border-bottom: 0; }
table.data .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
table.data tbody tr:hover { background: var(--surface-2); }
.who { display: flex; align-items: center; gap: 10px; min-width: 200px; }
.avatar { width: 30px; height: 30px; border-radius: 50%; background: var(--surface-2); object-fit: cover; flex: none; }
.platform-tag { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--ink-2); }
.dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
.dot-yt { background: var(--series-yt); }
.dot-tt { background: var(--series-tt); }
.err { color: var(--critical); font-size: 12px; display: inline-flex; align-items: center; gap: 5px; }
.muted { color: var(--muted); }

.vthumb { width: 96px; aspect-ratio: 16 / 9; border-radius: 6px; object-fit: cover; background: var(--surface-2); display: block; }
.vtitle { font-weight: 600; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; max-width: 420px; }
.bar-cell { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }
.bar { height: 8px; border-radius: 0 4px 4px 0; min-width: 2px; }

.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; padding: 18px; }
.tile { text-decoration: none; display: flex; flex-direction: column; gap: 6px; }
.tile-media { position: relative; border-radius: 8px; overflow: hidden; background: var(--surface-2); aspect-ratio: 16 / 9; }
.tile-media .blur { position: absolute; inset: -12px; width: calc(100% + 24px); height: calc(100% + 24px); object-fit: cover; filter: blur(14px) brightness(0.7); }
.tile-media .fg { position: relative; object-fit: contain; }
.tile-media img { width: 100%; height: 100%; object-fit: cover; display: block; }
.tile-badge { position: absolute; right: 6px; bottom: 6px; background: rgba(0, 0, 0, 0.75); color: #fff; font-size: 11.5px; padding: 1px 6px; border-radius: 4px; font-weight: 600; }
.tile-trend { position: absolute; left: 6px; top: 6px; background: rgba(0, 0, 0, 0.75); color: #fff; font-size: 11.5px; padding: 1px 6px; border-radius: 4px; font-weight: 600; }
.tile-meta { font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 6px; }
.tile-title { font-weight: 600; line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.tile-stats { font-size: 12px; color: var(--ink-2); display: flex; flex-wrap: wrap; justify-content: space-between; gap: 2px 10px; }
.pager { display: flex; justify-content: space-between; align-items: center; padding: 12px 18px; border-top: 1px solid var(--border); color: var(--muted); font-size: 12.5px; }
.empty { padding: 40px 20px; text-align: center; color: var(--ink-2); }
.refetching { opacity: 0.6; transition: opacity 0.2s; }

.connect { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-bottom: 16px; }
.connect .card { padding: 18px; display: flex; flex-direction: column; gap: 10px; }
.connect form { display: flex; gap: 8px; flex-wrap: wrap; }
.status-ok { color: var(--up); font-size: 12px; }

.signin { min-height: 100vh; display: grid; place-items: center; padding: 16px; }
.signin .card { padding: 32px; max-width: 380px; width: 100%; text-align: center; display: flex; flex-direction: column; gap: 14px; }

.mobile-nav { display: none; }
@media (max-width: 1100px) { .kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); } .charts { grid-template-columns: 1fr; } }
@media (max-width: 760px) {
  .shell { grid-template-columns: minmax(0, 1fr); }
  .sidebar { display: none; }
  .mobile-nav { display: flex; gap: 6px; overflow-x: auto; padding: 10px 16px; background: var(--surface); border-bottom: 1px solid var(--border); }
  .mobile-nav a { text-decoration: none; padding: 6px 10px; border-radius: 7px; font-weight: 600; font-size: 13px; color: var(--ink-2); white-space: nowrap; }
  .mobile-nav a[aria-current="page"] { background: var(--surface-2); color: var(--ink); }
  .main { padding: 16px; }
  .kpis { grid-template-columns: 1fr 1fr; gap: 10px; }
  .kpi-value { font-size: 24px; }
  .connect { grid-template-columns: 1fr; }
  .input { min-width: 0; width: 100%; }
}

/* Radar AI */
.radar-ai { position: fixed; right: 24px; bottom: 22px; z-index: 80; display: flex; flex-direction: column; align-items: flex-end; gap: 12px; }
.radar-launch { border: 1px solid rgba(255,255,255,.12); border-radius: 15px; background: #0b0b0b; color: #fff; padding: 10px 15px 10px 10px; display: flex; align-items: center; gap: 10px; box-shadow: 0 12px 34px rgba(0,0,0,.22); cursor: pointer; text-align: left; }
.radar-launch:hover { transform: translateY(-1px); box-shadow: 0 15px 38px rgba(0,0,0,.28); }
.radar-launch > span:last-child { display: flex; flex-direction: column; line-height: 1.25; }
.radar-launch b { font-size: 13px; }
.radar-launch small { font-size: 10.5px; color: rgba(255,255,255,.62); }
.radar-orb { width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center; background: radial-gradient(circle at 30% 25%, #a5e5ff 0, #3a83ff 28%, #7158e8 62%, #151629 100%); box-shadow: inset 0 0 0 1px rgba(255,255,255,.28), 0 0 18px rgba(69,126,255,.38); flex: none; }
.radar-orb i { width: 13px; height: 13px; border: 2px solid rgba(255,255,255,.92); border-top-color: transparent; border-radius: 50%; transform: rotate(32deg); }
.radar-orb.small { width: 32px; height: 32px; border-radius: 10px; }
.radar-panel { width: min(390px, calc(100vw - 32px)); height: min(610px, calc(100vh - 110px)); background: var(--surface); border: 1px solid var(--border); border-radius: 16px; box-shadow: 0 22px 70px rgba(0,0,0,.25); display: grid; grid-template-rows: auto minmax(0,1fr) auto auto; overflow: hidden; animation: radar-in .18s ease-out; }
@keyframes radar-in { from { opacity: 0; transform: translateY(10px) scale(.98); } }
.radar-head { padding: 13px 14px; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center; background: var(--surface); }
.radar-head > div:first-child { display: flex; align-items: center; gap: 10px; }
.radar-head > div:first-child > div { display: flex; flex-direction: column; }
.radar-head b { font-size: 13px; }
.radar-head small { color: var(--muted); font-size: 11px; }
.radar-head-actions { display: flex; gap: 4px; }
.radar-head-actions button { width: 30px; height: 30px; display: grid; place-items: center; border: 0; border-radius: 7px; background: transparent; cursor: pointer; font-size: 16px; }
.radar-head-actions button:hover { background: var(--surface-2); }
.radar-messages { overflow-y: auto; padding: 16px; display: flex; flex-direction: column; gap: 10px; background: color-mix(in srgb, var(--page) 72%, var(--surface)); }
.radar-message { max-width: 88%; padding: 10px 12px; border-radius: 12px; font-size: 13px; line-height: 1.45; }
.radar-message.assistant { align-self: flex-start; background: var(--surface); border: 1px solid var(--border); border-bottom-left-radius: 4px; }
.radar-message.user { align-self: flex-end; background: var(--accent); color: var(--accent-ink); border-bottom-right-radius: 4px; }
.radar-message.thinking { display: flex; gap: 4px; align-items: center; min-height: 36px; }
.radar-message.thinking i { width: 5px; height: 5px; border-radius: 50%; background: var(--muted); animation: radar-dot 1s infinite alternate; }
.radar-message.thinking i:nth-child(2) { animation-delay: .16s; }.radar-message.thinking i:nth-child(3) { animation-delay: .32s; }
@keyframes radar-dot { to { transform: translateY(-4px); opacity: .35; } }
.radar-prompts { display: flex; flex-wrap: wrap; gap: 6px; }
.radar-prompts button { border: 1px solid var(--border); background: var(--surface); color: var(--ink-2); border-radius: 999px; padding: 6px 9px; font-size: 11.5px; cursor: pointer; }
.radar-prompts button:hover { color: var(--ink); border-color: var(--axis); }
.radar-compose { display: grid; grid-template-columns: 34px minmax(0,1fr) 34px; gap: 7px; padding: 11px 12px; border-top: 1px solid var(--border); background: var(--surface); }
.radar-compose input { min-width: 0; border: 1px solid var(--border); background: var(--surface-2); border-radius: 9px; padding: 8px 10px; outline: none; }
.radar-compose input:focus { border-color: var(--axis); box-shadow: 0 0 0 2px var(--border); }
.radar-mic,.radar-send { border: 0; border-radius: 9px; cursor: pointer; font-weight: 800; }
.radar-mic { background: var(--surface-2); color: var(--ink-2); font-size: 10px; }
.radar-mic.active { color: #fff; background: #e54242; animation: radar-pulse 1s infinite; }
@keyframes radar-pulse { 50% { box-shadow: 0 0 0 5px rgba(229,66,66,.18); } }
.radar-send { background: var(--accent); color: var(--accent-ink); font-size: 18px; }
.radar-send:disabled { opacity: .3; cursor: default; }
.radar-panel footer { padding: 0 12px 9px; background: var(--surface); color: var(--muted); text-align: center; font-size: 10px; }
@media (max-width: 760px) { .radar-ai { right: 12px; bottom: 12px; }.radar-panel { height: calc(100vh - 92px); }.radar-launch small { display: none; } }
.mobile-nav svg { display: none; }
@media (max-width: 760px) {
  .filters > * { max-width: 100%; }
  .seg { overflow-x: auto; }
  .card-head { flex-direction: column; }
  .legend { justify-content: flex-start; }
}

/* Dashboard layout */
.kpi-row { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; }
.kpi-row .spark { width: 46%; max-width: 140px; height: 34px; flex: none; }
.spark { display: block; width: 100%; overflow: visible; }
.dash-grid { display: grid; grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr); gap: 14px; margin-bottom: 18px; }
.trending { padding: 16px 18px; }
.link { font-size: 12.5px; font-weight: 600; text-decoration: none; color: var(--ink-2); white-space: nowrap; }
.link:hover { color: var(--ink); text-decoration: underline; }
.trend-list { list-style: none; margin: 4px 0 0; padding: 0; display: flex; flex-direction: column; }
.trend-list li a { display: grid; grid-template-columns: 16px 76px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 8px 6px; border-radius: 8px; text-decoration: none; }
.trend-list li a:hover { background: var(--surface-2); }
.rank { color: var(--muted); font-weight: 700; font-size: 12px; text-align: center; }
.tthumb { width: 76px; aspect-ratio: 16 / 9; border-radius: 5px; object-fit: cover; background: var(--surface-2); display: block; }
.tinfo { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.ttitle { font-weight: 600; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tmeta { font-size: 11.5px; color: var(--muted); display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tbar { height: 4px; border-radius: 0 4px 4px 0; display: block; }
.tgain { display: flex; flex-direction: column; align-items: flex-end; }
.tgain b { font-size: 14px; }
.tgain small { color: var(--muted); font-size: 11px; white-space: nowrap; }
.section-bar { display: flex; justify-content: space-between; align-items: flex-end; gap: 10px; margin-bottom: 10px; }
.ch-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 12px; }
.ch-card { text-align: left; cursor: pointer; padding: 14px 16px 12px; display: flex; flex-direction: column; gap: 10px; transition: box-shadow 0.15s, border-color 0.15s; }
.ch-card:hover { border-color: var(--axis); }
.ch-card[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--accent); }
.ch-top { display: flex; align-items: center; gap: 10px; min-width: 0; }
.ch-name { display: flex; flex-direction: column; min-width: 0; }
.ch-name b { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ch-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.ch-stats > div { display: flex; flex-direction: column; }
.ch-label { font-size: 11.5px; color: var(--muted); }
.ch-value { font-size: 19px; font-weight: 650; }
.ch-sub { font-size: 12px; color: var(--ink-2); }
.ch-card .spark { height: 36px; }
.ch-foot { font-size: 11.5px; }
.chip { border: 1px solid var(--border); background: var(--surface-2); border-radius: 999px; padding: 6px 12px; font-weight: 600; font-size: 12.5px; cursor: pointer; display: inline-flex; gap: 8px; align-items: center; }
.card-head .seg button { padding: 4px 10px; font-size: 12px; }
@media (max-width: 1100px) { .dash-grid { grid-template-columns: 1fr; } }
.tmeta .dot, .platform-tag .dot { flex: none; }
.section-bar { flex-wrap: wrap; }
@media (max-width: 760px) {
  .kpi-row { flex-direction: column; align-items: stretch; gap: 4px; }
  .kpi-row .spark { width: 100%; max-width: none; height: 28px; }
}

/* language switch */
.lang { display: inline-flex; align-self: flex-start; background: var(--surface-2); border: 1px solid var(--border); border-radius: 8px; padding: 2px; gap: 2px; }
.lang button { background: none; border: 0; text-decoration: none; padding: 3px 10px; border-radius: 6px; font-size: 12px; font-weight: 700; letter-spacing: .04em; color: var(--muted); cursor: pointer; }
.lang button[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); }
.lang-center { align-self: center; }
.lang-mobile { display: none; }
@media (max-width: 760px) { .lang-mobile { display: inline-flex; margin: 10px 16px 0; } }

/* monthly report */
.report-summary { padding: 16px 18px; margin-bottom: 14px; }
.report-summary p { margin: 0; font-size: 15px; line-height: 1.6; }
.report-foot { font-size: 12px; margin-top: 18px; }
@media print {
  :root, :root[data-theme] { --page: #fff !important; --surface: #fff !important; --surface-2: #f1f0ec !important; --ink: #0b0b0b !important; --ink-2: #333 !important; --muted: #666 !important; --border: rgba(0,0,0,.18) !important; --accent: #0b0b0b !important; --accent-ink: #fff !important; }
  body { background: #fff !important; color: #0b0b0b !important; }
  .sidebar, .mobile-nav, .lang-mobile, .radar-ai, .no-print, .filters { display: none !important; }
  .shell { display: block !important; }
  .main { padding: 0 !important; }
  .card { box-shadow: none !important; break-inside: avoid; }
}

/* Content insights and video context reuse the dashboard's existing tokens. */
.insight-filters label,.metadata-form label { display:grid; gap:6px; font-size:12px; color:var(--ink-2); }
.insight-filters { align-items:end; }
.sample-note { display:block; color:var(--ink-2); font-size:12px; margin-top:4px; }
.video-link { display:flex; align-items:center; gap:12px; max-width:520px; color:var(--ink); text-decoration:none; }
.video-link:hover { text-decoration:underline; }
.video-link .tthumb { flex:none; }
.detail-grid { display:grid; grid-template-columns:1.3fr 1fr; gap:24px; margin-bottom:24px; align-items:start; }
.video-cover { width:100%; max-height:360px; object-fit:contain; background:var(--surface-2); border-radius:var(--radius); }
.video-heading { font-size:26px; max-width:850px; }
.metadata-form { display:grid; gap:12px; padding:24px; }
.metadata-form .input,.metadata-form .select { width:100%; }
.detail-metrics { padding:20px; display:flex; flex-wrap:wrap; gap:24px; }
.detail-metrics b { display:block; font-size:22px; margin-top:6px; }
@media(max-width:760px){.detail-grid{grid-template-columns:1fr}.insight-filters label{width:100%}.insight-filters .select{width:100%}.video-heading{font-size:22px}}
