import { Img } from "./Img";
type Targets={month:string;views:number;followers:number;publications:number};
export function Brief(){
 const [month,setMonth]=useState(currentMonth());
 useEffect(()=>{const m=new URLSearchParams(window.location.search).get("month");if(m&&/^20\d{2}-(0[1-9]|1[0-2])$/.test(m))setMonth(m);},[]);
 const {data,error}=useLive<MonthlyReport>(`/api/report?month=${month}`,120000);
 const {data:target,reload}=useLive<{goals:Targets}>(`/api/goals?month=${month}`,120000);
 const canManage=useCanManage();const [form,setForm]=useState({views:"",followers:"",publications:""});const [editing,setEditing]=useState(false);const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);
 useEffect(()=>{if(target)setForm({views:String(target.goals.views||""),followers:String(target.goals.followers||""),publications:String(target.goals.publications||"")});},[target]);
 async function save(e:React.FormEvent){e.preventDefault();setBusy(true);try{const r=await fetch("/api/goals",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({month,...Object.fromEntries(Object.entries(form).map(([k,v])=>[k,Number(v)]))})});const body=await r.json();setMessage(r.ok?"Monthly targets saved.":body.error);if(r.ok){setEditing(false);reload();}}catch{setMessage("Could not save targets.");}finally{setBusy(false);}}
 const leader=data?[...data.accounts].sort((a,b)=>b.viewsGained-a.viewsGained)[0]:null;const k=data?.kpis;
 const comparison=k&&data?.comparisonReady?pctChange(k.viewsGained,k.viewsGainedPrev):null;
 const health=data?.accounts.filter(a=>a.lastError||!a.lastPolledAt||Date.now()-new Date(a.lastPolledAt).getTime()>1800000)||[];
 const targetRows=k?[{key:"views" as const,label:"Measured views gained",value:k.viewsGained},{key:"followers" as const,label:"Net followers",value:k.followersGained},{key:"publications" as const,label:"Videos published",value:k.videosPublished}]:[];
 return <><div className="page-head"><div><h1>Leadership brief</h1><p>Monthly progress, content winners and channel health. Updates automatically.</p></div><div className="head-actions"><input type="month" className="input" aria-label="Brief month" max={currentMonth()} min="2026-01" value={month} onChange={e=>{if(e.target.value)setMonth(e.target.value);}}/><button className="btn" onClick={async()=>{try{await navigator.clipboard.writeText(`${window.location.origin}/brief?month=${month}`);setMessage("Link copied. Your team still needs an approved sign-in.");}catch{setMessage("Copy the page address from your browser.");}}}>Copy view link</button></div></div>
 {error&&<div className="banner" role="alert">{error}</div>}{message&&<p role="status">{message}</p>}
 {data&&k&&<>
 <div className="brief-strip"><span><i className={`live-dot ${health.length?"stale":""}`}/> {health.length?`${health.length} channel(s) need attention`:"All channels reporting"}</span><span>{data.complete?"Completed month":"Month to date"} · Vietnam time</span><a href="/channels">Connection health</a></div>
 {!data.comparisonReady&&<div className="banner info">Tracking history is incomplete. Values show observed growth only. Percentage comparisons are withheld until all channels have a baseline for both periods.</div>}
 <section className="brief-takeaways"><article className="card"><small>01 / Growth</small><h2>{comparison==null?"Building a reliable baseline":`${comparison>=0?"+":""}${comparison.toFixed(1)}% measured views`}</h2><p>{comparison==null?"Growth before channel connection cannot be reconstructed from public counters.":data.complete?"Compared with the previous calendar month.":"Compared with the same elapsed time last month."}</p></article><article className="card"><small>02 / Leading channel</small><h2>{leader?.title||"No activity yet"}</h2><p>{leader?`${PLATFORM_LABEL[leader.platform]} · ${fmtFull(leader.viewsGained)} measured views gained this month.`:"Connect a channel to start collecting results."}</p></article><article className="card"><small>03 / Content output</small><h2>{k.videosPublished} videos published</h2><p>{signed(k.followersGained)} net followers across tracked accounts. <a href="/insights">Explore content patterns</a></p></article></section>
 <div className="section-bar"><h2 className="card-title">Monthly targets</h2>{canManage&&<button className="btn" onClick={()=>setEditing(!editing)}>{editing?"Cancel":"Edit targets"}</button>}</div>
 <div className="brief-targets">{targetRows.map(row=>{const goal=target?.goals[row.key]||0;return <article className="card kpi" key={row.key}><div className="kpi-label">{row.label}</div><div className="kpi-value">{fmtFull(row.value)}</div><p className="muted">{goal?`${fmtFull(goal)} target · ${(row.value/goal*100).toFixed(1)}% achieved`:"No target set"}</p>{goal>0&&<progress aria-label={`${row.label} progress`} max={goal} value={Math.max(0,Math.min(row.value,goal))}/>}</article>;})}</div>
 {editing&&<form className="card target-form" onSubmit={save}>{(["views","followers","publications"] as const).map(key=><label key={key}>{key ==="publications"?"Videos published":key ==="followers"?"Net new followers":"Views gained"}<input className="input" type="number" min={0} step={1} max={key==="publications"?100000:key==="followers"?1e10:1e12} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>)}<button className="btn btn-primary" disabled={busy}>{busy?"Saving...":"Save targets"}</button></form>}
 <div className="section-bar"><h2 className="card-title">Channel contribution</h2><a href={`/report?month=${month}`}>Full monthly report</a></div>
 <section className="card table-wrap"><table className="data"><thead><tr><th>Channel</th><th className="num">Followers</th><th className="num">Net new</th><th className="num">Measured views</th><th className="num">Engagements</th><th className="num">Published</th></tr></thead><tbody>{data.accounts.map(a=><tr key={a.id}><td><a href={`/?platform=${a.platform}&account=${a.id}&range=30d`}>{a.title}</a><small className="sample-note">{PLATFORM_LABEL[a.platform]}</small></td><td className="num">{fmtFull(a.followers)}</td><td className="num">{signed(a.followersGained)}</td><td className="num">{fmtFull(a.viewsGained)}</td><td className="num">{fmtFull(a.engagementsGained)}</td><td className="num">{a.videosPublished}</td></tr>)}</tbody></table></section>
 <section className="card section"><div className="card-head"><h2 className="card-title">Videos driving measured growth</h2></div><ol className="trend-list">{data.topVideos.filter(v=>v.viewsGained>0).map(v=><li key={v.id}><a href={`/library/${v.id}`}><Img className="tthumb" src={v.thumbnailUrl}/><span className="tinfo"><b>{v.title}</b><small className="sample-note">{v.accountTitle} · {PLATFORM_LABEL[v.platform]}</small></span><span className="tgain"><b>+{fmtFull(v.viewsGained)}</b><small>measured views</small></span></a></li>)}</ol>{!data.topVideos.some(v=>v.viewsGained>0)&&<div className="empty">No measured video growth in this period yet.</div>}</section>
 <p className="muted">Source: YouTube Data API, YouTube Analytics and TikTok Display API. Checked {new Date(data.generatedAt).toLocaleString("en-GB")}. Sync runs on a periodic schedule, not instantly after publication.</p>
 </>}{!data&&!error&&<div className="empty">Loading monthly brief...</div>}</>;
}

