  library: "M4 6h16v2H4zm0 5h16v2H4zm0 5h10v2H4z",
  report: "M6 2h9l5 5v15H6V2zm8 1.5V8h4.5L14 3.5zM8 12h8v1.5H8V12zm0 3h8v1.5H8V15zm0 3h5v1.5H8V18z",
