// YouTube Data API v3 (public statistics). Quota per poll per channel:
// channels.list 1 + playlistItems.list 1 + videos.list 1 per 50 videos.

const BASE = "https://www.googleapis.com/youtube/v3";

export type FetchFn = typeof fetch;

export interface YtChannel {
  id: string;
  title: string;
  handle: string | null;
  avatarUrl: string | null;
  uploadsPlaylistId: string | null;
  subscribers: number | null;
  totalViews: number | null;
  videoCount: number | null;
}

export interface YtVideo {
  id: string;
  title: string;
  publishedAt: string | null;
  thumbnailUrl: string | null;
  durationSec: number | null;
  views: number;
  likes: number | null;
  comments: number | null;
}

export class YouTubeError extends Error {}

function num(v: unknown): number | null {
  if (v === undefined || v === null || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

async function call<T>(path: string, params: Record<string, string>, apiKey: string, fetchFn: FetchFn): Promise<T> {
  const qs = new URLSearchParams({ ...params, key: apiKey });
  const res = await fetchFn(`${BASE}/${path}?${qs}`);
  const body = (await res.json().catch(() => ({}))) as { error?: { message?: string } };
  if (!res.ok) throw new YouTubeError(`YouTube ${path} ${res.status}: ${body.error?.message ?? "request failed"}`);
  return body as T;
}

/** Accepts @handle, a channel ID (UC...), or a youtube.com URL in either form. */
export function parseChannelInput(input: string): { id: string } | { handle: string } {
  const s = input.trim();
  const fromUrl = s.match(/youtube\.com\/(?:channel\/(UC[\w-]{22})|(@[\w.-]+))/i);
  if (fromUrl?.[1]) return { id: fromUrl[1] };
  if (fromUrl?.[2]) return { handle: fromUrl[2] };
  if (/^UC[\w-]{22}$/.test(s)) return { id: s };
  if (/^@?[\w.-]{3,}$/.test(s)) return { handle: s.startsWith("@") ? s : `@${s}` };
  throw new YouTubeError("Enter a channel @handle, channel ID (UC...) or channel URL.");
}

interface RawChannel {
  id: string;
  snippet?: { title?: string; customUrl?: string; thumbnails?: { default?: { url?: string } } };
  statistics?: { viewCount?: string; subscriberCount?: string; hiddenSubscriberCount?: boolean; videoCount?: string };
  contentDetails?: { relatedPlaylists?: { uploads?: string } };
}

function toChannel(c: RawChannel): YtChannel {
  return {
    id: c.id,
    title: c.snippet?.title ?? c.id,
    handle: c.snippet?.customUrl ?? null,
    avatarUrl: c.snippet?.thumbnails?.default?.url ?? null,
    uploadsPlaylistId: c.contentDetails?.relatedPlaylists?.uploads ?? null,
    subscribers: c.statistics?.hiddenSubscriberCount ? null : num(c.statistics?.subscriberCount),
    totalViews: num(c.statistics?.viewCount),
    videoCount: num(c.statistics?.videoCount),
  };
}

const CHANNEL_PARTS = "snippet,statistics,contentDetails";

export async function resolveChannel(input: string, apiKey: string, fetchFn: FetchFn = fetch): Promise<YtChannel> {
  const parsed = parseChannelInput(input);
  const params: Record<string, string> =
    "id" in parsed ? { part: CHANNEL_PARTS, id: parsed.id } : { part: CHANNEL_PARTS, forHandle: parsed.handle };
  const res = await call<{ items?: RawChannel[] }>("channels", params, apiKey, fetchFn);
  const first = res.items?.[0];
  if (!first) throw new YouTubeError(`Channel "${input}" not found.`);
  return toChannel(first);
}

/** Batch lookup, up to 50 IDs per request. */
export async function fetchChannels(ids: string[], apiKey: string, fetchFn: FetchFn = fetch): Promise<YtChannel[]> {
  const out: YtChannel[] = [];
  for (let i = 0; i < ids.length; i += 50) {
    const res = await call<{ items?: RawChannel[] }>(
      "channels",
      { part: CHANNEL_PARTS, id: ids.slice(i, i + 50).join(","), maxResults: "50" },
      apiKey,
      fetchFn,
    );
    out.push(...(res.items ?? []).map(toChannel));
  }
  return out;
}

/** ISO 8601 duration (PT1H2M3S) to seconds. */
export function parseDuration(iso: string | undefined): number | null {
  const m = iso?.match(/^P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/);
  if (!m) return null;
  const [, d, h, mi, s] = m.map((x) => Number(x ?? 0));
  return d * 86400 + h * 3600 + mi * 60 + s;
}

/**
 * Every video gets a thumbnail: the 480px "high" image (its 4:3 letterbox crops away
 * cleanly in a 16:9 frame), else medium, else the predictable i.ytimg.com URL.
 */
export function videoThumbnail(id: string, thumbs?: Record<string, { url?: string } | undefined>): string {
  return thumbs?.high?.url ?? thumbs?.medium?.url ?? `https://i.ytimg.com/vi/${encodeURIComponent(id)}/hqdefault.jpg`;
}

/** Most recent uploads (newest first) with their current statistics. */
export async function fetchRecentVideos(
  uploadsPlaylistId: string,
  apiKey: string,
  limit = 50,
  fetchFn: FetchFn = fetch,
  since?: string,
): Promise<YtVideo[]> {
  const ids: string[] = [];
  let pageToken: string | undefined;
  const seen = new Set<string>();
  do {
    const list = await call<{ nextPageToken?: string; items?: { contentDetails?: { videoId?: string; videoPublishedAt?: string } }[] }>(
      "playlistItems", { part: "contentDetails", playlistId: uploadsPlaylistId, maxResults: String(Math.min(limit - ids.length, 50)), ...(pageToken ? { pageToken } : {}) }, apiKey, fetchFn,
    );
    let crossedCutoff = false;
    for (const item of list.items ?? []) {
      const v = item.contentDetails;
      if (since && v?.videoPublishedAt && v.videoPublishedAt < since) { crossedCutoff = true; continue; }
      if (v?.videoId) ids.push(v.videoId);
    }
    if (crossedCutoff || !list.nextPageToken || seen.has(list.nextPageToken)) break;
    pageToken = list.nextPageToken;
    seen.add(pageToken);
  } while (ids.length < limit);
  return fetchVideoIds(ids.slice(0, limit), apiKey, fetchFn);
}

/** Refresh stored videos even after they leave the newest uploads page. */
export async function fetchVideoIds(ids: string[], apiKey: string, fetchFn: FetchFn = fetch): Promise<YtVideo[]> {
  const out: YtVideo[] = [];
  for (let offset = 0; offset < ids.length; offset += 50) {
  const res = await call<{
    items?: {
      id: string;
      snippet?: { title?: string; publishedAt?: string; thumbnails?: Record<string, { url?: string } | undefined> };
      statistics?: { viewCount?: string; likeCount?: string; commentCount?: string };
      contentDetails?: { duration?: string };
    }[];
  }>("videos", { part: "snippet,statistics,contentDetails", id: ids.slice(offset, offset + 50).join(",") }, apiKey, fetchFn);
  out.push(...(res.items ?? []).map((v) => ({
    id: v.id,
    title: v.snippet?.title ?? v.id,
    publishedAt: v.snippet?.publishedAt ?? null,
    thumbnailUrl: videoThumbnail(v.id, v.snippet?.thumbnails),
    durationSec: parseDuration(v.contentDetails?.duration),
    views: num(v.statistics?.viewCount) ?? 0,
    likes: num(v.statistics?.likeCount),
    comments: num(v.statistics?.commentCount),
  })));
  }
  return out;
}

src/lib/ytAnalytics.ts:
// YouTube Analytics API (owner-only metrics: average view duration, impressions CTR).
// A channel manager authorises once with the same Google OAuth client used for sign-in.
// Scopes are read-only. Google refresh tokens do not expire, so only the refresh token is stored (encrypted).

import type { FetchFn } from "./youtube";

const AUTH_URL = "https://accounts.google.com/o/oauth2/v2/auth";
const TOKEN_URL = "https://oauth2.googleapis.com/token";
const REPORTS = "https://youtubeanalytics.googleapis.com/v2/reports";
const CHANNELS = "https://www.googleapis.com/youtube/v3/channels";
export const ANALYTICS_SCOPES = "https://www.googleapis.com/auth/yt-analytics.readonly https://www.googleapis.com/auth/youtube.readonly";

export class AnalyticsError extends Error {}

export interface AnalyticsConfig {
  clientId: string;
  clientSecret: string;
  redirectUri: string;
}

export function analyticsConfig(origin: string): AnalyticsConfig | null {
  const clientId = process.env.AUTH_GOOGLE_ID;
  const clientSecret = process.env.AUTH_GOOGLE_SECRET;
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret, redirectUri: `${origin}/api/youtube/callback` };
}

export function buildAuthUrl(cfg: AnalyticsConfig, state: string, anyAccount = false): string {
  const qs = new URLSearchParams({
    client_id: cfg.clientId,
    redirect_uri: cfg.redirectUri,
    response_type: "code",
    scope: ANALYTICS_SCOPES,
    access_type: "offline",
    // select_account lets a manager pick the Brand Account that owns the channel; consent forces a refresh token.
    prompt: "select_account consent",
    state,
  });
  // Only offer Workspace accounts of the first allowed domain, so a personal Gmail can not be picked by mistake.
  const domain = (process.env.ALLOWED_EMAIL_DOMAINS ?? "").split(",")[0]?.trim();
  if (domain && !anyAccount) qs.set("hd", domain);   // anyAccount: a channel manager outside the company (e.g. a Gmail) connects their channel
  return `${AUTH_URL}?${qs}`;
}

async function token(body: Record<string, string>, fetchFn: FetchFn) {
  const res = await fetchFn(TOKEN_URL, { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body: new URLSearchParams(body) });
  const json = (await res.json().catch(() => ({}))) as { access_token?: string; refresh_token?: string; error?: string; error_description?: string };
  if (!res.ok || !json.access_token) throw new AnalyticsError(`Google token request failed: ${json.error_description ?? json.error ?? res.status}`);
  return json as { access_token: string; refresh_token?: string };
}

export function exchangeCode(cfg: AnalyticsConfig, code: string, fetchFn: FetchFn = fetch) {
  return token({ client_id: cfg.clientId, client_secret: cfg.clientSecret, redirect_uri: cfg.redirectUri, grant_type: "authorization_code", code }, fetchFn);
}

export async function refreshAccessToken(cfg: Pick<AnalyticsConfig, "clientId" | "clientSecret">, refreshToken: string, fetchFn: FetchFn = fetch) {
  return (await token({ client_id: cfg.clientId, client_secret: cfg.clientSecret, grant_type: "refresh_token", refresh_token: refreshToken }, fetchFn)).access_token;
}

/** The channel the signed-in Google account (or the Brand Account it picked) owns. */
export async function myChannelId(accessToken: string, fetchFn: FetchFn = fetch): Promise<string> {
  const res = await fetchFn(`${CHANNELS}?part=id&mine=true`, { headers: { Authorization: `Bearer ${accessToken}` } });
  const json = (await res.json().catch(() => ({}))) as { items?: { id: string }[]; error?: { message?: string } };
  const id = json.items?.[0]?.id;
  if (!res.ok || !id) throw new AnalyticsError(json.error?.message ?? "This Google account has no YouTube channel. Pick the channel's Brand Account.");
  return id;
}

export interface Stats {
  views: number | null;
  impressions: number | null;
  /** Percent, as returned by YouTube (5.2 means 5.2%). */
  ctr: number | null;
  avdSec: number | null;
  avgViewPct: number | null;
}

type Row = Record<string, number | string>;

async function report(accessToken: string, channelId: string, params: Record<string, string>, fetchFn: FetchFn): Promise<Row[]> {
  const qs = new URLSearchParams({ ids: `channel==${channelId}`, ...params });
  const res = await fetchFn(`${REPORTS}?${qs}`, { headers: { Authorization: `Bearer ${accessToken}` } });
  const json = (await res.json().catch(() => ({}))) as { columnHeaders?: { name: string }[]; rows?: (number | string)[][]; error?: { message?: string } };
  if (!res.ok) throw new AnalyticsError(`YouTube Analytics ${res.status}: ${json.error?.message ?? "request failed"}`);
  const names = (json.columnHeaders ?? []).map((h) => h.name);
  return (json.rows ?? []).map((r) => Object.fromEntries(r.map((v, i) => [names[i], v])));
}

const num = (v: unknown) => (typeof v === "number" && Number.isFinite(v) ? v : null);
const day = (d: Date) => d.toISOString().slice(0, 10);
const CORE = "views,averageViewDuration,averageViewPercentage";
const IMPRESSIONS = "videoThumbnailImpressions,videoThumbnailImpressionsClickRate";

function toStats(core: Row | undefined, imp: Row | undefined): Stats {
  return {
    views: num(core?.views),
    avdSec: num(core?.averageViewDuration),
    avgViewPct: num(core?.averageViewPercentage),
    impressions: num(imp?.videoThumbnailImpressions),
    ctr: num(imp?.videoThumbnailImpressionsClickRate),
  };
}

/** Impressions metrics are fetched separately: if YouTube refuses them for a channel, AVD still works. */
async function optional(run: () => Promise<Row[]>): Promise<Row[]> {
  try {
    return await run();
  } catch {
    return [];
  }
}

export async function fetchChannelStats(accessToken: string, channelId: string, days: number, now = new Date(), fetchFn: FetchFn = fetch): Promise<Stats> {
  const range = { startDate: day(new Date(now.getTime() - days * 86400_000)), endDate: day(now) };
  const core = await report(accessToken, channelId, { ...range, metrics: CORE }, fetchFn);
  const imp = await optional(() => report(accessToken, channelId, { ...range, metrics: IMPRESSIONS }, fetchFn));
  return toStats(core[0], imp[0]);
}

/** Per-video stats for the channel's best 200 videos in the window, keyed by YouTube video id. */
export async function fetchVideoStats(accessToken: string, channelId: string, days: number, now = new Date(), fetchFn: FetchFn = fetch): Promise<Map<string, Stats>> {
  const range = { startDate: day(new Date(now.getTime() - days * 86400_000)), endDate: day(now), dimensions: "video", maxResults: "200" };
  const core = await report(accessToken, channelId, { ...range, metrics: CORE, sort: "-views" }, fetchFn);
  const imp = await optional(() => report(accessToken, channelId, { ...range, metrics: IMPRESSIONS, sort: "-videoThumbnailImpressions" }, fetchFn));
  const impById = new Map(imp.map((r) => [String(r.video), r]));
  return new Map(core.map((r) => [String(r.video), toStats(r, impById.get(String(r.video)))]));
}

/** Calendar month, kept separate from rolling windows in the reporting cache. */
export async function fetchMonthStats(accessToken: string, channelId: string, month: string, now = new Date(), fetchFn: FetchFn = fetch): Promise<Stats> {
  const [year, m] = month.split("-").map(Number);
  const lastDay = new Date(Date.UTC(year, m, 0)).toISOString().slice(0, 10);
  const endDate = lastDay < day(now) ? lastDay : day(now);
  const range = { startDate: `${month}-01`, endDate };
  const core = await report(accessToken, channelId, { ...range, metrics: CORE }, fetchFn);
  const imp = await optional(() => report(accessToken, channelId, { ...range, metrics: IMPRESSIONS }, fetchFn));
  return toStats(core[0], imp[0]);
}

